// Four specific sub-goals per B1 → B2 lesson (three for the checks: no new vocabulary, so language form, reading and use),
// shared by all three sheets (docs/LESSON_QUALITY_CONTRACT.md A2–A3, owner 2026-10-13). The learner goal (canDo) stays in
// the module files. `tags` gives a task its real sub-goal where the generic block default was wrong (a word-bank gap
// trains vocabulary, not form).
export const B2_LESSON_GOALS = {
  "b1b2-001": {"canDo": "Ma räägin ühe minuti ilma abita, saan aru arvamusloost keelevahetuse kohta ning kirjutan keelekoolile umbes 140-sõnalise viisaka kirja, kus palun tingivas kõneviisis.", "goals": {"g_read": "Õpilane saab aru umbes 450-sõnalisest arvamusloost keelevahetuse kohta, leiab põhjused ja järeldab autori hoiaku.", "g_notice": "Õpilane moodustab viisaka palve tingivas kõneviisis (saaksite, sooviksin, oleks võimalik) ja valib adressaadi järgi registri (sa / te, pöördumine ja lõpp).", "g_use": "Õpilane räägib külma ülesandena 1 minuti, helistab keelekooli ja reageerib ootamatule infole ning kirjutab päris keelekoolile umbes 140-sõnalise kirja."}},
  "b1b2-002": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest kodutööde jagamisest, annan sõbrale ühe minutiga nõu ja kirjutan umbes 140-sõnalise vastuse, kus seon mõtted sidesõnadega.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest kodutööde jagamisest ja nähtamatust tööst ning vastab 10 küsimusele.", "g_notice": "Õpilane seob mõtted sidesõnadega (kuna, kuigi, seetõttu, samas, nii et, enne kui), hoiab tegusõna õigel kohal ja muudab käsu nõuandeks.", "g_use": "Õpilane annab sõbrannale pärast 2-minutilist ettevalmistust 1-minutilise häälsõnumiga nõu ja kirjutab umbes 140-sõnalise vastuse ilma valmis fraasideta."}},
  "b1b2-003": {"canDo": "Ma loen arvamusartiklit neljapäevasest töönädalast, järeldan autori seisukoha, kaitsen väitlusel oma poolt märksõnakaardi abil ja kirjutan umbes 180-sõnalise arvamusteksti; ajaväljendi järel panen tegusõna teisele kohale.", "goals": {"g_read": "Õpilane leiab arvamusartiklist poolt- ja vastuargumendid, järeldab autori seisukoha ja kasutab artikli argumente väitluses.", "g_notice": "Õpilane kasutab sageduse, aja ja kestuse väljendeid (reedeti, kord kuus, kaheksa tundi), paneb tegusõna ajaväljendi järel teisele kohale ja ütleb vaidluse lause koosoleku keeles.", "g_use": "Õpilane kaitseb väitlusel märksõnakaardi abil oma poolt, vastab vastuargumendile, põhjendab oma häält ja kirjutab umbes 180-sõnalise arvamusteksti."}},
  "b1b2-004": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest töö kõrvalt õppimisest, võrdlen kursusi aja, raha ja väsimuse järgi, lepin pereliikmega kokku nädalaplaani ja kirjutan tööandjale umbes 140-sõnalise palve.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest töö kõrvalt õppimisest ja vastab 10 küsimusele.", "g_notice": "Õpilane moodustab keskvõrde ja ülivõrde (kallim kui, kõige paindlikum, parim), kasutab võrreldes + -ga ja erinevalt + -st ning kirjutab pere lause tööandjale sobivas registris.", "g_use": "Õpilane leiab infolüngaga vestluses kursuse, reageerib pereliikme takistustele, lepib kokku nädalaplaani ja kirjutab tööandjale umbes 140-sõnalise kirja."}},
  "b1b2-005": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (valikvastus, väide ja lõik) umbes 550-sõnalise arvamusartikli põhjal, ka järeldusküsimused.", "g_notice": "Õpilane jaotab kontrolli aja osade vahel ja teab iga osa toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane räägib paralleelülesandena pärast 2-minutilist ettevalmistust 1 minuti ja arutleb märksõnakaartidega ning jõuab kokkuleppele."}, "tags": {"005_p_rpart": "g_notice", "005_t_spart": "g_notice"}},
  "b1b2-006": {"canDo": "Ma saan aru umbes 450-sõnalisest tekstist selle kohta, kelle poole Eestis millegi pärast pöörduda, räägin uuele naabrile, kuhu ja kelle poole ta peab pöörduma, ning kirjutan talle umbes 140-sõnalise vastuse koos päris lingiga.", "goals": {"g_read": "Õpilane saab aru umbes 450-sõnalisest tekstist riigi, linna ja maja ülesannetest, leiab, kelle poole millegi pärast pöörduda, ja järeldab autori vihjed.", "g_notice": "Õpilane kasutab tegusõna koos õige käändega (pöörduma kelle poole, teatama millest, teavitama keda, osalema millel, loobuma millest) ja ütleb naabrile öeldu ametlikus kirjas.", "g_use": "Õpilane räägib külma ülesandena 1 minuti, selgitab uuele naabrile ootamatute küsimuste kiuste, kuhu pöörduda, ja kirjutab talle umbes 140-sõnalise kirja päris lingiga."}},
  "b1b2-007": {"canDo": "Ma saan aru umbes 3,5-minutilisest telefonikõnest perearstikeskusse, lepin registratuuriga kokku aja ka siis, kui tekib takistus, ning annan kokkuleppe pereliikmele edasi kaudses kõnes umbes 140-sõnalises sõnumis.", "goals": {"g_read": "Õpilane saab aru kahe häälega telefonikõnest perearstikeskusse (takistus, kokkulepe, mida kaasa võtta) ja vastab 10 küsimusele, ka järeldusküsimustele.", "g_notice": "Õpilane annab teise sõnad edasi kaudses kõnes (ütles, et; küsis, kas; palus, et + tingiv; registratuuri sõnul; olevat) ja ütleb liiga otsese palve viisakalt.", "g_use": "Õpilane lepib registratuuriga varjatud infoga kõnes kokku sobiva aja, annab kokkuleppe pereliikmele edasi ja kirjutab umbes 140-sõnalise sõnumi."}},
  "b1b2-008": {"canDo": "Ma loen umbes 500-sõnalist artiklit ostja õigustest, järeldan autori nõuanded, räägin poe letis rahulikult ka siis, kui müüja ütleb „ei”, ja kirjutan müüjale umbes 140-sõnalise kaebuse ametlikus stiilis.", "goals": {"g_read": "Õpilane leiab artiklist ostja õigused ja hea kaebuse sammud ning järeldab autori hoiaku kaebamise ja vigase keele kohta.", "g_notice": "Õpilane seob põhjuse ja tagajärje ametlikus stiilis (-mise tõttu, seoses …-ga, tulenevalt …-st, mistõttu, tänu …-le) ja muudab vihase lause rahulikuks.", "g_use": "Õpilane nõuab poe letis varjatud infoga vestluses lahendust ja kirjutab ilma valmis fraasideta umbes 140-sõnalise pretensiooni neljas sammus."}},
  "b1b2-009": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest kortermajast tormi ajal, arutlen märksõnakaartidega, mida maja peaks tegema, ja kirjutan maja vestlusesse umbes 180-sõnalise arvamuse, kus kasutan tingimuslauseid.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest kortermajast tormi ajal ja maja otsusest ning parandab valed väited.", "g_notice": "Õpilane kasutab päris ja mõeldud tingimust (juhul kui; kui meil oleks …, töötaks …; kui oleks olnud …, oleksime …; olenemata sellest, kas) ja kirjutab naabrite lause juhatuse teatesse.", "g_use": "Õpilane väitleb märksõnakaartidega ühise generaatori üle, reageerib uuele asjaolule, jõuab ühise otsuseni ja kirjutab umbes 180-sõnalise arvamuse."}},
  "b1b2-010": {"goals": {"g_read": "Õpilane saab eksami vormis aru infotunnist uutele elanikele ja intervjuust kortermaja plaanist B (lüngad, õige või vale).", "g_notice": "Õpilane jaotab kontrolli aja osade vahel ja teab iga osa toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane räägib paralleelülesandena pärast 2-minutilist ettevalmistust 1 minuti ja arutleb märksõnakaartidega ning jõuab ühise seisukohani."}, "tags": {"010_p_listen": "g_read", "010_p_tf": "g_read", "010_p_lpart": "g_notice", "010_t_spart": "g_notice"}},
  "b1b2-011": {"canDo": "Ma saan aru umbes 450-sõnalisest tekstist selle kohta, kuidas Eesti peolaud on muutunud, räägin raadiointervjuus oma pere toidutraditsioonist umbisikulises minevikus ja kirjutan raamatukogu kogumikku umbes 140-sõnalise pere toiduloo.", "goals": {"g_read": "Õpilane saab aru umbes 450-sõnalisest tekstist sellest, kuidas peolaud on talust tänapäevani muutunud, ja järeldab autori vihjed ja hoiaku.", "g_notice": "Õpilane räägib kombest umbisikulises minevikus (söödi, tehti, peeti, ei ostetud, oli pandud), eristab seda lihtminevikust ja kirjutab pere jutu kogumiku teksti.", "g_use": "Õpilane kirjutab külma ülesandena 5 minutiga arvamuse, jutustab varjatud infoga raadiointervjuus oma pere toidust ja kirjutab umbes 140-sõnalise pere toiduloo."}},
  "b1b2-012": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest matkamisest Eesti looduses, toetan oma soovitust kogemusega (olen käinud …, eelmisel kevadel …), lepin matkajuhiga kokku, kas ja kuidas matkale tulen, ning kirjutan talle umbes 140-sõnalise vastuse päris matkaraja lingiga.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest matkajuhi nõuannetest (laudtee, eksimine, lõkkekoht, puugid) ja vastab 10 küsimusele, ka järeldusküsimustele.", "g_notice": "Õpilane toetab soovitust kogemusega: täisminevik ajaväljenditega (juba aastaid, seni, sellest ajast saadik, viimasel ajal) ja üks tõestav kord lihtminevikus.", "g_use": "Õpilane lepib matkajuhiga varjatud infoga kõnes kokku raja, aja ja varustuse ning kirjutab umbes 140-sõnalise vastuse päris matkaraja lingiga."}},
  "b1b2-013": {"canDo": "Ma loen umbes 500-sõnalist teksti 1991. aasta augustipäevadest, panen sündmused ajajoonele ja järeldan, mis oli juhtunud enne, räägin lapsele ootamatute küsimuste kiuste, miks 20. august on riigipüha, ning kirjutan umbes 140-sõnalise selgituse päris allikaga.", "goals": {"g_read": "Õpilane saab aru umbes 500-sõnalisest tekstist 1991. aasta augustipäevadest, paneb sündmused ajajoonele ja järeldab autori vihjed.", "g_notice": "Õpilane näitab sündmuste järjekorda enneminevikuga ja sidenditega (selleks ajaks, kui; pärast seda, kui … oli; niipea kui; alles siis, kui; enne kui) ning kirjutab pere jutu ajalooteksti.", "g_use": "Õpilane selgitab lapsele varjatud infoga vestluses, mis juhtus 1991. aasta augustis, ja kirjutab umbes 140-sõnalise selgituse päris allikaga."}},
  "b1b2-014": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest telefonipettusest, ütlen tingiva kõneviisi minevikus, mida oleks pidanud tegema teisiti, arutlen väitlusel märksõnakaartidega, kes peaks kahju kandma, ja kirjutan umbes 180-sõnalise arvamuse.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest telefonipettusest (petukõne sammud, kahetsus, panga vastus) ja parandab valed väited.", "g_notice": "Õpilane väljendab kahetsust ja kriitikat tingiva kõneviisi minevikus (oleksin pidanud + -ma; poleks tohtinud, oleks võinud + -da; kui oleksin …, ei oleks …) ja kirjutab pere jututoa lause pangale.", "g_use": "Õpilane väitleb märksõnakaartidega, kes peab kandma pettuse kahju, reageerib uuele asjaolule, jõuab ühise ettepanekuni ja kirjutab umbes 180-sõnalise arvamuse."}},
  "b1b2-015": {"goals": {"g_read": "Õpilane saab eksami vormis aru umbes 350-sõnalisest artiklist laulupeost (küsimused, valikvastused) ja valib lünktekstis õige mineviku vormi.", "g_notice": "Õpilane jaotab kontrolli aja osade vahel ja teab iga osa toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane kirjutab paralleelülesandena 5 minutiga arvamuse ja raamatukogule umbes 140-sõnalise kirja, kus mineviku ajad näitavad sündmuste järjekorda."}, "tags": {"015_p_read": "g_read", "015_p_mc": "g_read", "015_p_cloze": "g_read", "015_p_rpart": "g_notice", "015_t_wpart": "g_notice"}},
  "b1b2-016": {"canDo": "Ma saan aru umbes 500-sõnalisest tekstist üürniku ja üürileandja vastutusest, vaidlen telefonis rahulikult tagatisraha kinnipidamise vastu ja kirjutan üürileandjale umbes 140-sõnalise kirja, kus sihitis on õige ka ametlikus lauses.", "goals": {"g_vocab": "Õpilane räägib ilma abita ühest murest, mille ta pidi ise lahendama, ja oma kodu üleandmisest sõnadega tagatisraha, harilik kulumine, kahju, üleandmisakt, kinni pidama.", "g_read": "Õpilane saab aru umbes 500-sõnalisest tekstist tagatisrahast, harilikust kulumisest ja kahjust ning järeldab autori vihjed ja hoiaku.", "g_notice": "Õpilane valib sihitise vormi ka ametlikus lauses: käsu, „tuleb + da” ja umbisikulise järel nimetav (saatke hinnapakkumine, vahetati lukk), eituses osastav (akti ei koostatud), arvsõna järel osastav.", "g_use": "Õpilane vaidleb varjatud infoga telefonikõnes tagatisraha kinnipidamise vastu, lepib kokku summa ja tähtaja ning kirjutab ilma antud alguseta umbes 140-sõnalise kirja."}, "tags": {"016_d_cold": "g_vocab", "016_t_plan": "g_vocab"}},
  "b1b2-017": {"canDo": "Ma saan aru umbes 3,5-minutilisest kõnest klassijuhatajaga õppekäigu reeglitest, tõlgin ametliku teate pereliikmele lihtsasse keelde (ka siis, kui ta ütleb midagi ootamatut) ja kirjutan klassijuhatajale umbes 140-sõnalise kirja.", "goals": {"g_read": "Õpilane saab aru kahe häälega kõnest klassijuhatajaga (kellaaeg, maksmine, nõusolek, telefon, järeletulija, allergia) ja vastab 10 küsimusele, ka järeldusküsimustele.", "g_notice": "Õpilane kasutab ametliku teate vorme (on kohustatud + ma; palutakse, on lubatud, on keelatud + da; -mata, -des) ja ütleb ametliku lause pereliikmele lihtsalt.", "g_use": "Õpilane seletab vanaemale varjatud infoga vestluses õppekäigu päeva, reageerib ootamatule ja kirjutab klassijuhatajale umbes 140-sõnalise kirja."}},
  "b1b2-018": {"canDo": "Ma saan aru umbes 500-sõnalisest tekstist täiskasvanute hobidest ja ühistegevusest, väitlen märksõnakaartidega, kas omavalitsus peaks täiskasvanute huviringe toetama, ja kirjutan umbes 180-sõnalise arvamuse päris näitega.", "goals": {"g_vocab": "Õpilane räägib oma vabast ajast ja huvidest sõnadega huvitegevus, harrastaja, proov, liituma, loobuma, kogukond.", "g_read": "Õpilane saab aru umbes 500-sõnalisest tekstist sellest, miks täiskasvanud ühistegevust otsivad, ja järeldab autori hoiaku hobi kasulikkuse kohta.", "g_notice": "Õpilane kasutab nimisõnade ja harvemate tegusõnade rektsiooni (osalemine kooris, vastutus mille eest, kokkupuude millega; suhtuma millesse, loobuma millest, pühenduma millele, põhinema millel).", "g_use": "Õpilane väitleb märksõnakaartidega täiskasvanute huviringide toetamise üle, reageerib uuele asjaolule, jõuab ühise ettepanekuni ja kirjutab umbes 180-sõnalise arvamuse päris näitega."}, "tags": {"018_d_talk": "g_vocab", "018_t_plan": "g_vocab"}},
  "b1b2-019": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest reisija õigustest, kui rong või buss jääb ära, seletan oma plaani B pereliikmele ka siis, kui ta ei taha seda kuulda, ja kirjutan talle umbes 140-sõnalise juhendi päris lingiga.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest reisija õigustest (tõend, asendusbuss, hüvitis, kaebus, järelevalve) ja parandab valed väited.", "g_notice": "Õpilane kasutab ametlikus kaebuses koos sihitist, tegevusnime ja rektsiooni (Pöördun teie poole seoses …-ga; Palun hüvitada kulud; Nõuan tagastamist; teavitama keda millest).", "g_use": "Õpilane seletab vanaemale varjatud infoga vestluses oma plaani B ja kirjutab talle umbes 140-sõnalise juhendi päris lingiga."}},
  "b1b2-020": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemis- ja kuulamisülesanded (valikvastus, lühivastused, vormivalikuga lünktekst, lausepank; teated, intervjuu, õige või vale) üürimise, kooli, huviringi ja reisimise teemal.", "g_notice": "Õpilane jaotab proovieksami aja osade vahel ja teab iga osaoskuse toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane kirjutab vedajale umbes 140-sõnalise kaebuse ja 180-sõnalise arutluse ning räägib paralleelülesandena ilma fraasideta 1 minuti oma lahendatud murest ja arutleb märksõnakaartidega."}, "tags": {"020_p_notes": "g_read", "020_p_listen": "g_read", "020_p_tf": "g_read", "020_d_rpart": "g_notice", "020_p_lpart": "g_notice", "020_t_wpart": "g_notice", "020_t_spart": "g_notice"}},
  "b1b2-021": {"canDo": "Ma saan aru umbes 450-sõnalisest tekstist kella keeramise vaidlusest ja eristan fakti, arvamust ja ennustust, ütlen raadiointervjuus 1 minutiga oma seisukoha ning kirjutan uudise alla umbes 140-sõnalise kommentaari, kus näitan allikat ja seda, kui kindel ma olen.", "goals": {"g_read": "Õpilane saab aru umbes 450-sõnalisest tekstist kella keeramise vaidlusest, eristab fakti, arvamust ja ennustust ning järeldab autori hoiaku.", "g_notice": "Õpilane näitab allikat ja kindlust (uuringute järgi, pole välistatud, et …, on tõenäoline, et …, vaevalt + jaatav tegusõna, ma kahtlen, kas …) ja annab teise väite edasi kaudses kõneviisis (olevat).", "g_use": "Õpilane kirjutab külma ülesandena 5 minutiga arvamuse, ütleb varjatud infoga raadiointervjuus 1 minutiga oma seisukoha ja kirjutab umbes 140-sõnalise kommentaari."}},
  "b1b2-022": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadioväitlusest jõulukuuse üle ja järeldan kõnelejate hoiaku, väitlen märksõnakaartidega ning kirjutan umbes 180-sõnalise arutluse, kus viitan kuuldud argumentidele.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadioväitlusest päris ja kunstkuuse üle, paneb kirja kummagi poole argumendid ja järeldab kõnelejate hoiaku.", "g_notice": "Õpilane ehitab arutluse lõigu (teemalause, põhjus, näide, järeldus; ühelt poolt … teiselt poolt, lisaks sellele, sellest järeldub, et …) ja paneb sidendi ning allikaviite järel tegusõna teisele kohale.", "g_use": "Õpilane väitleb märksõnakaartidega, reageerib uuele asjaolule, viitab allikale ja kirjutab saate põhjal umbes 180-sõnalise arutluse."}},
  "b1b2-023": {"canDo": "Ma saan aru umbes 500-sõnalisest tekstist laste ekraaniajast ja järeldan autori hoiaku, juhin pere nõupidamist, kus tunnistan teise mõtet ja lükkan vastuargumendi viisakalt ümber, ning kirjutan lastevanemate foorumisse umbes 140-sõnalise vastuse.", "goals": {"g_read": "Õpilane saab aru umbes 500-sõnalisest tekstist laste ekraaniajast, leiab argumendid ja vastuargumendid ning järeldab autori hoiaku.", "g_notice": "Õpilane tunnistab teise mõtet ja lükkab selle viisakalt ümber (tõsi küll …, kuid; isegi kui …, ei tähenda see, et …; olgugi et; see ei pea paika, sest …; vaatamata + -le) ja pehmendab ettepaneku tingivas kõneviisis.", "g_use": "Õpilane juhib varjatud infoga pere nõupidamist, lepib kokku kolm ekraanireeglit ja kirjutab umbes 140-sõnalise vastuse foorumisse."}},
  "b1b2-024": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest selle kohta, mida teekond tööle päriselt maksab, võrdlen oma teekonna kahte võimalust päris sõiduplaani põhjal, põhjendan valikut kahtlejale ja kirjutan vallale umbes 180-sõnalise ettepaneku.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest teekonna kuludest ja valikust ning otsustab, kas väited on õiged või valed, ka järeldusväide.", "g_notice": "Õpilane võrdleb täpselt (võrreldes + -ga, erinevalt + -st, mida … seda, kaks korda kallim, mitte niivõrd …, kuivõrd …, eelistama mida millele, seevastu, samas kui).", "g_use": "Õpilane võrdleb oma teekonna kahte võimalust Peatus.ee andmetega, põhjendab valikut varjatud infoga vestluses kahtlejale ja kirjutab vallale umbes 180-sõnalise ettepaneku."}},
  "b1b2-025": {"goals": {"g_read": "Õpilane saab eksami vormis aru neljast lühiteatest ja väitlustreeneri raadiointervjuust (lüngad, õige või vale).", "g_notice": "Õpilane jaotab kontrolli aja osade vahel ja teab iga osa toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane kirjutab paralleelülesandena 5 minutiga arvamuse ja umbes 160-sõnalise arutluse „Minu seisukoht”, kus kasutab mooduli keelt (allikas ja kindlus, sidendid, vastuväide, võrdlus)."}, "tags": {"025_p_notes": "g_read", "025_p_listen": "g_read", "025_p_tf": "g_read", "025_p_lpart": "g_notice", "025_t_wpart": "g_notice"}},
  "b1b2-026": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest töövestlusest ja järeldan nõustaja hoiaku, vastan töövestlusel küsimusele „Rääkige endast” konkreetse näitega ja kirjutan päris kuulutusele umbes 140-sõnalise kaaskirja.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest sellest, kuidas töövestlusel endast rääkida, vastab 10 küsimusele ja järeldab nõustaja vihjed ja hoiaku.", "g_notice": "Õpilane kasutab olevat ja saavat käänet tegusõna rektsioonis (pean seda oluliseks, kursus osutus kasulikuks, kujunes ametiks, näen end juhina, mind võeti tööle praktikandina) ning ütleb jutu CV keeles.", "g_use": "Õpilane räägib külma ülesandena 1 minuti ilma abita, vastab varjatud infoga töövestlusel küsimusele „Rääkige endast” päris kuulutuse järgi ja kirjutab umbes 140-sõnalise kaaskirja."}},
  "b1b2-027": {"canDo": "Ma loen umbes 500-sõnalist töölepingut koos seaduse meelespeaga ja järeldan, millised punktid on töötajale ohtlikud, seletan sõbrale lihtsas keeles, mida enne allkirja muuta, ning kirjutan tööandjale umbes 140-sõnalise kirja.", "goals": {"g_read": "Õpilane loeb umbes 500-sõnalist töölepingut ja meelespead, leiab punktid, mis seadusele ei vasta, ja järeldab, mis on töötajale ohtlik (ümbrikupalk, suulised kokkulepped).", "g_notice": "Õpilane kasutab lepingu keelt (kuni, vähemalt, hiljemalt; haigestumise korral, lepingu lõpetamisel; on kohustatud + ma, on õigus + da) ja ütleb ametliku lause lihtsalt.", "g_use": "Õpilane annab varjatud infoga vestluses sõbrale nõu enne allkirja ja kirjutab tööandjale umbes 140-sõnalise kirja."}},
  "b1b2-028": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest tülidest tööl ja järeldan lepitaja hoiaku, räägin kolleegiga murest faktidega ilma süüdistuseta ja lepin kokku lahenduse ning kirjutan juhile umbes 180-sõnalise kirja.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest tülidest tööl ja otsustab 10 väite kohta, kas need on õiged või valed, ka järeldusväited.", "g_notice": "Õpilane ütleb fakti ilma süüdistuseta (laouks jäi lahti, aruanne jäi tegemata, kokku lepiti, hilinemise tõttu) ja palub et-lausega tingivas kõneviisis (paluksin, et annaksid ette teada).", "g_use": "Õpilane räägib varjatud infoga vestluses teise inimesega murest, küsib põhjust, lepib kokku lahenduse ja kirjutab juhile umbes 180-sõnalise kirja."}},
  "b1b2-029": {"canDo": "Ma saan aru umbes 500-sõnalisest artiklist hobist äriks ja järeldan autori hoiaku, esitlen oma idee plaani pangatöötajale ka siis, kui ta toob ootamatu takistuse, ning kirjutan umbes 180-sõnalise arutluse, kas ja millistel tingimustel ma prooviksin.", "goals": {"g_read": "Õpilane saab aru umbes 500-sõnalisest artiklist ettevõtluskonto, FIE ja aja kohta ning järeldab autori vihjed ja hoiaku.", "g_notice": "Õpilane räägib plaanist ja tingimusest (kavatsen + da, hakkan + ma, selleks et, eeldusel / tingimusel, et …, seni kuni, -des) ja paneb tegusõna kõrvallause järel kohe.", "g_use": "Õpilane täidab idee kaardi, esitleb plaani varjatud infoga vestluses pangatöötajale ja kirjutab umbes 180-sõnalise arutluse."}},
  "b1b2-030": {"goals": {"g_read": "Õpilane lahendab eksami vormis umbes 500-sõnalise arvamusartikli põhjal valikvastused (ka järeldusküsimused) ja väite ning lõigu ülesande.", "g_notice": "Õpilane jaotab kontrolli aja osade vahel ja teab iga osa toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane räägib paralleelülesandena pärast 2-minutilist ettevalmistust 1 minuti ilma fraasideta ja arutleb märksõnakaartidega ning jõuab kokkuleppele."}, "tags": {"030_d_rpart": "g_notice", "030_t_spart": "g_notice"}},
  "b1b2-031": {"canDo": "Ma loen umbes 450-sõnalist artiklit koolivalikust pärast põhikooli ja järeldan autori hoiaku, annan lapsevanemale telefonis nõu ja lepin temaga kokku järgmise sammu ka siis, kui ta ütleb midagi ootamatut, ning kirjutan talle umbes 140-sõnalise kirja.", "goals": {"g_read": "Õpilane saab aru umbes 450-sõnalisest artiklist selle kohta, kuidas pere pärast põhikooli kooli valib (õppimiskohustus, gümnaasium, kutsekool), ja järeldab autori hoiaku.", "g_notice": "Õpilane kasutab rektsiooni kõrvallausega (sõltub sellest, kas …; huvitub sellest, kuidas …; keskendub sellele, et …; mures selle pärast, et …; olenevalt millest) ja paneb kõrvallause järel tegusõna kohe.", "g_use": "Õpilane kirjutab külma ülesandena 5 minutiga arvamuse, annab varjatud infoga telefonivestluses lapsevanemale nõu ja kirjutab umbes 140-sõnalise kirja."}},
  "b1b2-032": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest õppimise müütidest ja järeldan uurija hoiaku, edastan teiste väiteid allika ja kaugusega, räägin pereliikmega, kuidas eksamiks tõhusalt õppida, ja lepin temaga kokku plaani ning kirjutan talle umbes 140-sõnalise nõuande.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest õppimise müütidest, vastab 10 küsimusele ja järeldab uurija hoiaku.", "g_notice": "Õpilane näitab allikat ja kaugust (olevat näidanud, ei olevat leidnud, väidetakse, leiti, uurija rõhutab, et …, väidetavalt, reklaami väitel) ja eristab kuulujuttu uurimistulemusest.", "g_use": "Õpilane räägib ühe minuti ilma fraasideta, seletab varjatud infoga vestluses pereliikmele, kuidas õppida, teeb temaga plaani ja kirjutab umbes 140-sõnalise nõuande."}},
  "b1b2-033": {"canDo": "Ma loen umbes 450-sõnalist artiklit inimestest, kes vahetasid täiskasvanuna ametit, ja järeldan autori hoiaku, arutlen märksõnakaartidega ja kaitsen oma seisukohta ka siis, kui partner toob uue asjaolu, ning kirjutan umbes 180-sõnalise arutluse.", "goals": {"g_read": "Õpilane saab aru umbes 450-sõnalisest artiklist kahest täiskasvanust, kes vahetasid ametit, ja järeldab autori hoiaku ning riskid.", "g_notice": "Õpilane räägib mõeldud minevikust ja selle tagajärjest (kui ma oleksin siis õppinud, töötaksin praegu …; ilma et oleks plaani teinud; justkui oleks; oleks tasunud + da).", "g_use": "Õpilane kaitseb varjatud infoga arutelus märksõnakaartidega oma seisukohta, reageerib uuele asjaolule ja kirjutab umbes 180-sõnalise arutluse."}},
  "b1b2-034": {"canDo": "Ma saan aru umbes 3,5-minutilisest raadiosaatest selle kohta, kes maksab täiskasvanu õppimise eest, ja järeldan nõustaja hoiaku, leian päris kursuse ja lepin juhiga kokku õppepuhkuse ning kirjutan tööandjale umbes 140-sõnalise taotluse.", "goals": {"g_read": "Õpilane saab aru kahe häälega raadiosaatest õppimise rahastamisest (tööandja, õppepuhkus, tuludeklaratsioon, Töötukassa, koolitusleping) ja otsustab, kas väited on õiged või valed, ka järeldusväited.", "g_notice": "Õpilane kasutab ametliku teksti kesksõnu (registreeritud koolitaja, tasutud arve, lõpetanud õppija, õppiv töötaja, kehtiv leping) ja -mise + kaassõna (kursuse lõpetamise järel, lepingu lõpetamise korral) ning ütleb ametliku lause lihtsalt.", "g_use": "Õpilane leiab päris lehelt kursuse, lepib varjatud infoga vestluses juhiga kokku õppepuhkuse ja kirjutab umbes 140-sõnalise taotluse."}},
  "b1b2-035": {"goals": {"g_read": "Õpilane saab eksami vormis aru kuuest lühiteatest, mida kuuleb üks kord, ja karjäärinõustaja raadiointervjuust (lüngad, õige või vale).", "g_notice": "Õpilane jaotab kontrolli aja osade vahel ja teab iga osa toorpunkte ning lävendeid (Harno 60 %, KeeleSepp 70 % ja 80 %).", "g_use": "Õpilane kirjutab paralleelülesandena 5 minutiga arvamuse ja umbes 160-sõnalise teksti „Minu õpitee järgmine samm”, kus kasutab mooduli keelt (rektsioon kõrvallausega, allikas, tingiv kõneviis, ametlik vorm)."}, "tags": {"035_p_clips": "g_read", "035_p_listen": "g_read", "035_p_tf": "g_read", "035_p_lpart": "g_notice", "035_t_wpart": "g_notice"}},
  "b1b2-036": {"canDo": "Ma võrdlen reisivariante (transport, majutus, programm, hind), lepin kaaslasega kompromissi abil kokku nädalavahetuse plaani ja kirjeldan kohti kõrvallausega (koht, kus …; linn, kuhu …; telk, mille …).", "goals": {"g_vocab": "Õpilane räägib oma reisist ja selle planeerimisest sõnadega eelarve, majutus, ööbima, broneerima, praam, telkimiskoht, sihtkoht, varu, kompromiss.", "g_read": "Õpilane leiab teema avalehest reisi planeerimise faktid (praam, telkimiskoht, metsamaja, ravikindlustuskaart) ja võrdleb kolme reisivariandi hindu ja tingimusi.", "g_notice": "Õpilane täpsustab nimisõna kõrvallausega ja paneb asesõna õigesse käändesse (kus, kuhu, kust, mille, kellega, kelle juures).", "g_use": "Õpilane lepib reisikaaslasega kokku nädalavahetuse plaani ja kompromissi, teeb plaani B ja kirjutab 140–160-sõnalise kirja reisikaaslasele."}, "tags": {"036_d_talk": "g_vocab", "036_t_home": "g_vocab"}},
  "b1b2-037": {"canDo": "Ma räägin lennufirma teenindajaga ja nõuan viisakalt hüvitist, saan kuuldust aru, mis reisil juhtus, loen, mis mulle Euroopa Liidu reeglite järgi kuulub, edastan teenindaja sõnu kaudse kõneviisiga (lend olevat tühistatud) ja kirjutan kaebuse.", "goals": {"g_vocab": "Õpilane räägib oma reisimurest sõnadega tühistama, hilinema, hüvitis, pagas, kviitung, nõudma, erakorraline, kaebus.", "g_read": "Õpilane saab sõbranna häälsõnumist aru, mis lennujaamas juhtus, ja leiab kaartidelt, mis talle lennu tühistamise, hilinemise ja kohvri hilinemise korral kuulub.", "g_notice": "Õpilane edastab teise väidet mineviku kaudse kõneviisiga (olevat tühistatud, olevat jäänud), eristab seda faktist ja esitab viisaka nõude (Palun hüvitage …, Kas oleks võimalik …?).", "g_use": "Õpilane nõuab lennufirma teenindajalt ja korteri omanikult viisakalt oma õigusi ning kirjutab 140–160-sõnalise kaebuse."}, "tags": {"037_d_talk": "g_vocab", "037_t_home": "g_vocab"}},
  "b1b2-038": {"canDo": "Ma räägin Eesti ja teiste maade kommetest ettevaatlikult (sageli, enamasti, minu kogemuses, sõltub), saan raadiost aru, kuidas kultuurišokk käib, ja seletan uustulnukale ühe kombe tähendust konkreetse näitega.", "goals": {"g_vocab": "Õpilane räägib kommetest ja kultuurišokist sõnadega komme, kultuurišokk, kohanema, harjuma, üldistus, kinnine, viisakas, uustulnuk, usaldus.", "g_read": "Õpilane saab raadiosaatest aru, kuidas kultuurišokk käib, ja leiab kommete kaartidelt, mis on Eestis tavaline ja mida see tähendab.", "g_notice": "Õpilane pehmendab üldistust (sageli, enamasti, paljud, minu kogemuses + tegusõna teisel kohal, sõltub sellest, kas …) ja kasutab vormi peetakse milleks.", "g_use": "Õpilane seletab uustulnukale nelja kommet näite ja võrdlusega, arutleb kohanemise üle ja kirjutab 140–160-sõnalise kirja sõbrale, kes kolib Eestisse."}, "tags": {"038_d_talk": "g_vocab", "038_t_home": "g_vocab"}},
  "b1b2-039": {"canDo": "Ma räägin oma muuseumi-, kontserdi- või peokülastusest mineviku aegadega ja põhjendatud hinnanguga, valin külalisele sobiva koha või sündmuse ning soovitan seda suuliselt ja kirjalikult.", "goals": {"g_vocab": "Õpilane räägib oma kultuurielamusest sõnadega elamus, pettumus, väärt, soovitama, hinnang, näitus, etendus, külastama, külaline.", "g_read": "Õpilane täidab laulupeoloo lausetega, saab sugulase häälsõnumist aru, mida külaline vajab, ja valib kaartidelt talle sobiva koha või sündmuse.", "g_notice": "Õpilane valib loos õige mineviku (käisin, olen käinud, olin kuulnud) ja annab hinnangu (külastamist väärt, elamus, pettumus).", "g_use": "Õpilane soovitab sugulasele telefonis kohta ja plaani B, täidab kaardi „Minu soovitus külalisele” ja kirjutab reisifoorumisse 150–180-sõnalise soovituse."}, "tags": {"039_d_talk": "g_vocab", "039_t_home": "g_vocab"}},
  "b1b2-040": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel kodumaa reisidest, väide ja lõik, vormivalikuga arvustus, lausepank) reisimise ja kultuuri teemal vähemalt 70 % ulatuses.", "g_listen": "Õpilane saab aru neljast reisiteatest (lennujaam, praam, muuseumiöö, festival) ja tarbijanõustaja raadiointervjuust ning paneb kirja ajad, tingimused ja nõuanded.", "g_notice": "Õpilane kasutab vahehindamises õigesti kõrvallauseid, mineviku kaudset kõneviisi, ettevaatlikku üldistust, mineviku aegu ja tundide 21–35 vorme (rektsioon, tingiv, olev kääne).", "g_use": "Õpilane kirjutab külalistemajale 140-sõnalise kirja ja 180-sõnalise kokkuvõtte joonisest, räägib 1 minuti oma soovitusest külalisele ja jõuab arutelus ühisele seisukohale."}, "tags": {"040_p_notes": "g_listen", "040_p_listen": "g_listen", "040_p_tf": "g_listen"}},
  "b1b2-041": {"canDo": "Ma loen toidusilti ja tervisenumbreid, seon harjumuse ja selle tagajärje (tänu millele, mille tõttu, mistõttu, mõjuma millele) ning lepin pereliikmega poes kokku, mida me teisiti ostame.", "goals": {"g_vocab": "Õpilane räägib oma ostukorvist ja toiduharjumustest sõnadega harjumus, tagajärg, mõju, toitumine, koostis, säilimisaeg, soovitus, eelistama.", "g_read": "Õpilane leiab teema avalehest tervisenumbrid ja toidusildi reeglid, paneb pereliikme häälsõnumist kirja, millest valik sõltub, ning võrdleb kahe toote silti sajas grammis ja kilohinna järgi.", "g_notice": "Õpilane seob harjumuse ja tagajärje: tänu millele (hea), mille tõttu (halb), mistõttu, seetõttu ja mõjuma millele, ka tegusõnast nimisõnaga (vähese une tõttu).", "g_use": "Õpilane lepib poes pereliikmega kokku, mida osta, põhjendab numbritega ja kirjutab joonisest 150–170-sõnalise kokkuvõtte kommentaariga."}, "tags": {"041_d_talk": "g_vocab", "041_t_home": "g_vocab"}},
  "b1b2-042": {"canDo": "Ma räägin pereliikmega ja annan talle pehmet, realistlikku nõu tingiva kõneviisiga (võiksid, tasuks, oleks parem, kui …); enne seda saan kuuldust aru apteekri nõuannetest ja häälsõnumist ning leian koos teisega puuduva info (ravim teise inimese eest, 1220, gripivaktsiin apteegis, vanad ravimid).", "goals": {"g_vocab": "Õpilane räägib haigusest ja apteegist sõnadega apteeker, retseptiravim, käsimüügiravim, infoleht, isikukood, volitus, vaktsineerima, riskirühm, nõuandetelefon.", "g_read": "Õpilane leiab apteegi infokaardilt ja paneb enne kõnet tabelisse, mida retseptiravimi ostmiseks teise eest, gripisüstiks ja vanade ravimite jaoks vaja on.", "g_listen": "Õpilane saab aru raadiosaatest „Apteeker vastab” ja pereliikme häälsõnumist: kes mida küsib, kuhu helistada ja mis on tasuta.", "g_notice": "Õpilane muudab käsu pehmeks nõuandeks tingiva kõneviisiga: võiksid + da, peaksid + ma, tasuks, oleks parem, kui …, soovitaksin, kas sa ei tahaks, äkki.", "g_use": "Õpilane annab infovahetuses pereliikmele kolm pehmet nõuannet, kirjeldab nõuandetelefonil, mis juhtus, ja kirjutab 150–170-sõnalise kirja."}, "tags": {"042_d_talk": "g_vocab", "042_t_home": "g_vocab"}},
  "b1b2-043": {"canDo": "Ma räägin, kuidas ma liigun ja puhkan, loen liikumissoovitusi ja numbreid, kaitsen väitlusel oma seisukohta (trenn või puhkus) ja pakun kompromissi; eelistust ütlen pigem … kui …, selle asemel et ja mida …, seda ….", "goals": {"g_vocab": "Õpilane räägib oma liikumisest ja puhkusest sõnadega liikumine, tervisesport, mõõdukas, koormus, taastuma, väsimus, pigem, kompromiss, seisukoht.", "g_read": "Õpilane kontrollib liikumissoovitustest ja TAI numbritest oma arvamust ning leiab kahe raadiokuulaja jutust väitluseks argumendid ja näited.", "g_notice": "Õpilane ütleb eelistuse ja kompromissi: pigem … kui … (samas vormis), selle asemel et + da, mida + keskvõrre …, seda + keskvõrre …, eelistama mida millele.", "g_use": "Õpilane kaitseb väitlusel oma seisukohta kolme argumendiga, pakub kompromissi ja hääletab ning kirjutab 150–180-sõnalise arutluse."}, "tags": {"043_d_talk": "g_vocab", "043_t_home": "g_vocab"}},
  "b1b2-044": {"canDo": "Ma saan raadiost aru, kuidas harjumus tekib, teen endale kaheksa nädala plaani ühe muutuse jaoks (probleem → eesmärk → sammud → tulemus) ja esitlen seda; eesmärki ütlen selleks et- ja et-lausega, tulemust muutuma / saama + saav kääne.", "goals": {"g_vocab": "Õpilane räägib oma harjumustest ja plaanist sõnadega eesmärk, samm, kava, püsima, meeldetuletus, tagasilöök, toetama, mõõtma, tulemus.", "g_read": "Õpilane saab raadiost aru, kui kaua harjumus tekib ja mis aitab (lüngad), ning hindab kolme näidisplaani realistlikkust.", "g_notice": "Õpilane ütleb eesmärgi ja tulemuse: selleks et + da, et + tingiv (et ma ei unustaks), muutuma / saama / jääma + saav kääne.", "g_use": "Õpilane koostab kaardi „Minu 8 nädala muutus”, esitleb seda tervisepartnerile ja kirjutab 160–180-sõnalise sidusa plaani."}, "tags": {"044_d_talk": "g_vocab", "044_t_home": "g_vocab"}},
  "b1b2-045": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel saunast, väide ja lõik, vormivalikuga kiri, lausepank) tervise ja eluviisi teemal vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru viiest lühiteatest (apteek, Tartu Maraton, ujula, perearstikeskus, raamatukogu) ja liikumisnõustaja raadiointervjuust ning paneb kirja ajad, numbrid ja nõuanded.", "g_notice": "Õpilane kasutab kontrollis õigesti põhjust ja tagajärge, pehmet nõuannet, eelistust ning eesmärki ja tulemust päris sõnumites ja kirjas.", "g_use": "Õpilane kirjutab korteriühistule 140-sõnalise kirja ja 180-sõnalise kokkuvõtte joonisest ning räägib 1 minuti oma kaheksa nädala muutusest ja arutleb argumendikaartidega."}, "tags": {"045_p_notes": "g_listen", "045_p_listen": "g_listen", "045_p_tf": "g_listen"}},
  "b1b2-046": {"canDo": "Ma kirjutan sõbrale soovituse, kus kirjeldan tema iseloomu tegude kaudu, ja võrdlen oma kogemust faktidega sõpruse ja üksilduse kohta; moodustan omadussõnast nimisõna ja vastandi (lahkus, sõbralikkus, ebasõbralik, tänamatu).", "goals": {"g_vocab": "Õpilane räägib oma sõpradest ja sõprusest sõnadega usaldusväärne, tähelepanelik, otsekohene, kannatlik, hooliv, üksildus, tuttav, usaldus, aega veetma, toetama.", "g_read": "Õpilane kontrollib teema avalehe järgi oma oletusi sõpruse ja üksilduse kohta (Hall 2018, ELi üksilduse uuring, WHO, Harvardi uuring) ja leiab tuttava sõnumitest, mida üürileandja tema sõbra kohta teada tahab.", "g_notice": "Õpilane moodustab omadussõnast nimisõna ja vastandi (aus → ausus → ebaaus, kannatlik → kannatlikkus → kannatamatu, hoolima → hoolimatu) ja paneb need lauses õigesse vormi.", "g_use": "Õpilane kirjeldab telefonis sõbra kolme omadust koos tegudega, mängib omaduste äraarvamise mängu ja kirjutab 140–160-sõnalise soovituse."}, "tags": {"046_d_talk": "g_vocab", "046_t_home": "g_vocab"}},
  "b1b2-047": {"canDo": "Ma räägin rahamurest sõbraga nii, et suhe jääb alles: nimetan oma tunde täpselt, seon selle põhjuse ja tagajärjega (kuna, seetõttu, mistõttu), rõhutan sõnu -ki või -gi abil (isegi, ei tulnudki) ja kirjutan sõbrale selge, aga sõbraliku kirja.", "goals": {"g_vocab": "Õpilane räägib rahast ja sõprusest sõnadega laenama, võlg, tagasi maksma, pettunud, solvunud, ärritunud, piinlik, süütunne, kergendus, vältima.", "g_read": "Õpilane järeldab kahe sõbra sõnumitest ja häälsõnumist, mida kumbki tunneb ja miks, ning paneb kirja, mida võlgnik pakub.", "g_notice": "Õpilane seob tunde põhjuse ja tagajärjega (kuna, seetõttu, mistõttu) ja kasutab -ki/-gi vorme ning määramatuid asesõnu (ei tulnudki, isegi, keegi, mitte kellelegi).", "g_use": "Õpilane räägib sõbraga võlast mina-lausetega ja lepib kokku maksed, ütleb teisele tuttavale viisakalt ei ja kirjutab sõbrale 140–160-sõnalise kirja."}, "tags": {"047_d_talk": "g_vocab", "047_t_home": "g_vocab"}},
  "b1b2-048": {"canDo": "Ma saan aru naabri häälsõnumist, annan kahe naabri sõnad teineteisele täpselt ja erapooletult edasi (ütles, et …; küsis, kas …; palus …; väitis, et …), tean, mida seadus öörahu kohta ütleb, ja kirjutan korteriühistu juhatusele kokkuvõtte koos ettepanekuga.", "goals": {"g_vocab": "Õpilane räägib oma kodu helidest ja naabritest sõnadega naaber, öörahu, müra, segama, kaebus, korteriühistu, majagrupp, vahendaja, erapooletu, edasi andma.", "g_read": "Õpilane paneb naabri häälsõnumist kaudses kõnes kirja, mida too ütles ja palus, ning vastab teabeteksti järgi naabrite küsimustele öörahu kohta 1–3 sõnaga.", "g_notice": "Õpilane annab teise sõnad edasi kaudses kõnes (ütles, et …; küsis, kas / millal …; palus, et … / palus + da; väitis, et … olevat) ja muudab isikut, kohta ja aega.", "g_use": "Õpilane vahendab kahe naabri vahel erapooletult, kirjutab majagruppi rahuliku sõnumi, salvestab häälsõnumi ja kirjutab juhatusele 140–160-sõnalise kokkuvõtte."}, "tags": {"048_d_talk": "g_vocab", "048_t_home": "g_vocab"}},
  "b1b2-049": {"canDo": "Ma räägin pere või sõpradega läbi ja jõuan konkreetse kokkuleppeni, sest tean, mille poolest erineb seisukoht huvist: näitan, et mõistan teist (ma saan aru, et …), pakun pehmelt (mis oleks, kui …; kas saaksime …) ja seon järeleandmise tingimusega (olen nõus tingimusel, et …).", "goals": {"g_vocab": "Õpilane räägib pere vaidlustest ja kokkulepetest sõnadega kompromiss, kokkulepe, seisukoht, huvi, järele andma, tingimus, vastutasuks, lahendus, põlvkond, lepitaja.", "g_read": "Õpilane saab perelepitaja raadiosaatest aru, mille poolest erineb seisukoht huvist ja kuidas kokkuleppele jõuda, ning leiab rollikaartidelt iga põlvkonna tegeliku huvi.", "g_notice": "Õpilane pakub ja tingib õige kõneviisiga: mis oleks, kui + tingiv; kas saaksime; ma saan aru, et + kindel; tingimusel, et + kindel.", "g_use": "Õpilane jõuab läbirääkimismängus konkreetse kokkuleppeni, täidab oma kokkuleppe kaardi, vabandab nii, et see mõjub, ja kirjutab 150–180-sõnalise kokkuleppe kirja."}, "tags": {"049_d_talk": "g_vocab", "049_t_home": "g_vocab"}},
  "b1b2-050": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel „Tüli ei ole katastroof”, väide ja lõik, vormivalikuga kiri, lausepank) suhete teemal vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru neljast teatest (remont, keelekohvik, jõulupidu, vabatahtlikud) ja korteriühistu esimehe raadiointervjuust ning paneb kirja ajad, reeglid ja lahendused.", "g_notice": "Õpilane kasutab kontrollis õigesti iseloomu sõnu, -ki/-gi vorme, kaudset kõnet ja pehmet ettepanekut päris sõnumites ja kirjas.", "g_use": "Õpilane kirjutab naabrile 140-sõnalise vabandus- ja ettepanekukirja ja 180-sõnalise arutluse ning räägib 1 minuti oma kokkuleppest ja arutleb argumendikaartidega."}, "tags": {"050_p_notes": "g_listen", "050_p_listen": "g_listen", "050_p_tf": "g_listen"}},
  "b1b2-051": {"canDo": "Ma võrdlen oma oletusi faktidega Eesti pere kulude kohta, leian kuu väljavõttest väikesed lekked (tellimused, väikeostud) ja kirjutan pereliikmele ettepaneku, kuidas raha paremini planeerida; kasutan õigesti täis- ja osasihitist ning -alust (tühistasin tellimuse, ei tühistanud tellimust, raha ei jäänud üle).", "goals": {"g_vocab": "Õpilane räägib oma väikestest kuludest ja pere eelarvest sõnadega eelarve, kulu, sissetulek, tellimus, püsimakse, tühistama, säästma, reserv, planeerima, üle jääma, ilma päris summasid ütlemata.", "g_read": "Õpilane kontrollib teema avalehe järgi oma oletusi Eesti pere kulude kohta (Statistikaamet 2020, rahatarkuse uuring 2026) ja leiab ühe pere kuu väljavõttest lekked.", "g_notice": "Õpilane märkab tekstis täis- ja osasihitist ning olemasolu lause alust ja kasutab neid õigesti: tühistasin tellimuse, ei tühistanud tellimust, raha ei jäänud üle, arveid tuli palju.", "g_use": "Õpilane aitab perel väljavõttest lekked leida ja kolm sammu kokku leppida, täidab oma lekkekaardi ja kirjutab pereliikmele 160–180-sõnalise ettepaneku."}, "tags": {"051_d_talk": "g_vocab", "051_t_more": "g_vocab", "051_t_help": "g_read"}},
  "b1b2-052": {"canDo": "Ma kuulan ja loen reklaame, leian suure numbri tagant müügivõtte (ajasurve, võlts eelmine hind, pikenev prooviaeg), tean, mida seadus soodushinna kohta nõuab, ja räägin sõbraga, kas pakkumine tasub end ära; kasutan kesksõnu täiendina (kehtiv pakkumine, allahinnatud jope, enne alandust küsitud hind).", "goals": {"g_vocab": "Õpilane räägib sooduspakkumistest ja oma ostudest sõnadega allahindlus, soodushind, pakkumine, kehtima, piiratud, kampaania, tingimus, ahvatlema, eksitav, kahetsema.", "g_read": "Õpilane saab kuuest lühikesest reklaamist (üks kord kuulates) aru, mis tingimus peitub suure numbri taga, ja otsustab TTJA 30 päeva reegli järgi, kas pood käitub ausalt.", "g_notice": "Õpilane märkab reklaamides kesksõnu ja kasutab neid täiendina koos oma laiendiga: kehtiv pakkumine, automaatselt pikenev leping, enne alandust küsitud hind, ainult internetis müüdav toode.", "g_use": "Õpilane annab sõbrale kolme Black Friday pakkumise kohta põhjendatud nõu ja kirjutab naabritele 160–180-sõnalise hoiatuse koos oma ostureeglitega."}, "tags": {"052_d_talk": "g_vocab", "052_t_more": "g_vocab"}},
  "b1b2-053": {"canDo": "Ma saan tarbijanõustaja raadiosaatest aru, millal võin netiostust taganeda, loen e-poe tingimusi kriitiliselt ja kirjutan poele viisaka, aga kindla taganemisteate; mõistan umbisikulisi tingimusi (raha tagastatakse, kaupa ei vahetata) ja esitan nõude tingivas kõneviisis (paluksin, oleksin tänulik).", "goals": {"g_vocab": "Õpilane räägib ostudest, mis ei sobinud, sõnadega taganema, tagastama, kättesaamine, tingimused, tagasisaatmine, puudus, tellija, hea tahe, kinkekaart, klienditeenindus.", "g_read": "Õpilane saab tarbijanõustaja raadiosaatest aru, millal võib netiostust taganeda, loeb e-poe tingimusi ja seaduse lühikokkuvõtet ning vastab 1–3 sõnaga, millised tingimused kehtivad.", "g_notice": "Õpilane märkab tingimustes umbisikulist tegumoodi ja esitab nõude tingivas kõneviisis: raha tagastatakse, kaupa ei vahetata, paluksin, oleksin tänulik, kas saaksite.", "g_use": "Õpilane helistab e-poe klienditeenindusse ja nõuab viisakalt raha tagasi ning kirjutab kodus 160–180-sõnalise taganemisteate."}, "tags": {"053_d_talk": "g_vocab", "053_t_call": "g_use", "053_t_home": "g_vocab"}},
  "b1b2-054": {"canDo": "Ma loen pakkumisi ja võrdlen ostu rahastamise võimalusi (säästud, järelmaks, kiirlaen, kasutatud asi) kogukulu järgi, tean, mida seadus laenu hinna kohta ütleb, ja räägin väitlusel kaalutud seisukohast; vastuargumendiga arvestan sõnadega kuigi, küll … aga, seevastu.", "goals": {"g_vocab": "Õpilane räägib ostu rahastamisest sõnadega järelmaks, kiirlaen, intress, lepingutasu, kuumakse, krediidi kulukuse määr, kogukulu, viivis, maksehäire, kasutatud.", "g_read": "Õpilane loeb nelja pakkumise kaarti ja foorumi arutelu, arvutab kogukulu ning leiab argumendid poolt ja vastu.", "g_notice": "Õpilane märkab kaartidel kaalutud lauseid ja ühendab argumendi vastuargumendiga: kuigi …, siiski; küll …, aga; seevastu; ühest küljest …, teisest küljest; samas.", "g_use": "Õpilane kaitseb väitlusel kaalutud seisukohta, paneb kirja oma viis rahareeglit ja kirjutab kodus umbes 180-sõnalise arutluse."}, "tags": {"054_d_talk": "g_vocab", "054_t_more": "g_vocab"}},
  "b1b2-055": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel „Uus või kasutatud?”, väide ja lõik, vormidega kiri spordiklubile, lausepank) raha ja tarbimise teemal vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru neljast teatest (taaskasutuspunkt, rahatarkuse õhtu, elektrileping, kampaania) ja rahanõustaja raadiointervjuust taskuraha kohta ning paneb kirja ajad, numbrid ja nõuanded.", "g_notice": "Õpilane kasutab kontrollis õigesti täis- ja osasihitist, kesksõnu, umbisikulist tegumoodi, viisakat nõuet ja kaalutud seisukohta päris sõnumites ja kirjas.", "g_use": "Õpilane kirjutab korteriühistule ettepaneku ja arutluse rahatarkuse õpetamisest, räägib 1 minuti oma viiest rahareeglist ja jõuab arutelus ühisele seisukohale."}, "tags": {"055_p_notes": "g_listen", "055_p_listen": "g_listen", "055_p_tf": "g_listen"}},
  "b1b2-056": {"canDo": "Ma kasutan e-riigi teenuseid ise ja seletan teisele samm-sammult, kuidas asju aetakse (retsept kirjutatakse välja, paberit ei anta, dokument allkirjastatakse PIN2-ga); kirjutan abi vajavale inimesele selge juhendi.", "goals": {"g_vocab": "Õpilane räägib oma e-teenustest sõnadega ID-kaart, PIN-kood, sisse logima, allkirjastama, digiallkiri, retsept, välja kirjutama, riigiportaal, elukoht, hääletama.", "g_read": "Õpilane kontrollib teema avalehe järgi oma oletusi e-riigi kohta (PIN1 ja PIN2, digiretsept, e-hääletamine 2023, e-lahutus 2024, andmejälgija), paneb naabri häälsõnumist kirja tema kolm muret ja leiab kontrollpunktide kaartidelt vajalikud sammud.", "g_notice": "Õpilane moodustab umbisikulise oleviku ja selle eituse (logitakse, allkirjastatakse, tehakse, ei anta, ei küsita) ja kasutab neid juhendis.", "g_use": "Õpilane seletab naabrile telefonis samm-sammult kolm e-teenust, arutleb, kas riik peab jätma paberi võimaluse, ja kirjutab 140–160-sõnalise juhendi."}, "tags": {"056_d_talk": "g_vocab", "056_t_home": "g_vocab"}},
  "b1b2-057": {"canDo": "Ma loen töökoha või kursuse juhendit tehisintellekti kasutamise kohta, arutlen argumendikaartidega, mida tohib masinale anda ja mida mitte, ning sõnastan reeglid ametlikus stiilis (isikuandmete sisestamine on keelatud, vastutab saatja).", "goals": {"g_vocab": "Õpilane räägib tehisintellektist sõnadega tehisintellekt, vestlusrobot, isikuandmed, sisestama, kontrollima, vastutus, vastutama, kasutaja, lubatud, keelatud.", "g_read": "Õpilane vastab töökoha juhendi järgi kolleegide küsimustele 1–3 sõnaga (Harno B2 lugemine, osa 2b) ja järjestab tehisintellektile esitatud küsimused riski järgi.", "g_notice": "Õpilane muudab tegusõnalause -mine- ja -ja-vormiga ametlikuks lauseks ja tagasi (isikuandmete sisestamine, faktide kontrollimine, kasutaja, saatja).", "g_use": "Õpilane arutleb argumendikaartidega, vahetab poolt, jõuab kolme ühise reeglini ja kirjutab 160–180-sõnalise arutluse."}, "tags": {"057_d_talk": "g_vocab", "057_t_home": "g_vocab", "057_t_more": "g_read"}},
  "b1b2-058": {"canDo": "Ma kontrollin uudist või pilti enne jagamist (autor, kuupäev, teised allikad), saan aru uuringust, miks inimesed valet jagavad, kirjutan lühikese faktikontrolli umbisikulise mineviku ja täisminevikuga (jagati, on töödeldud, ei ole kinnitatud) ja annan sõbrale rahulikult nõu.", "goals": {"g_vocab": "Õpilane räägib uudistest ja valeinfost sõnadega valeinfo, allikas, väide, tõend, kinnitama, levima, jagama, töödeldud, kahtlane, usaldusväärne.", "g_read": "Õpilane taastab teksti uuringust, miks inimesed valet jagavad, lausepanga abil (Harno B2 lugemine, osa 4), paneb edasi saadetud häälsõnumist kirja selle allika ja palve ning otsustab viie postituse kohta, kas neid jagada.", "g_notice": "Õpilane kasutab umbisikulist minevikku ja täisminevikku ning nende eitust (jagati, leiti, on kasutatud, ei ole kinnitatud) faktikontrollis.", "g_use": "Õpilane veenab sõpra võltsitud postitust kustutama, mängib tõese ja vale pealkirja mängu ja kirjutab sõpradele 150–170-sõnalise faktikontrolli."},"tags": {"058_d_talk": "g_vocab", "058_t_home": "g_vocab"}},
  "b1b2-059": {"canDo": "Ma saan aru, milliseid õigusi mul oma andmete üle on (nõusolek, andmepäring, kustutamine, andmejälgija), muudan privaatsustingimuste ametliku keele lihtsaks ja vastupidi (andmete kogumine ↔ andmeid kogutakse) ning koostan ja esitlen oma digireeglid.", "goals": {"g_vocab": "Õpilane räägib oma rakendustest ja andmetest sõnadega privaatsus, nõusolek, küpsis, asukoht, luba, kustutama, andmed, seaded, jälgima, keelduma.", "g_read": "Õpilane saab andmekaitsejuristi raadiointervjuust aru oma õigustest (Harno B2 kuulamine, osa 2) ja valib viie kontrolli kaardilt need, mida ta oma telefonis teeb.", "g_notice": "Õpilane muudab privaatsustingimuste -mine-fraasi lihtsaks umbisikuliseks lauseks ja vastupidi (asukoha jagamine ↔ asukohta jagatakse).", "g_use": "Õpilane koostab kaardi „Minu digireeglid”, esitleb seda 1 minutiga, arutleb teavituste eksperimendi üle ja kirjutab firmale 140–160-sõnalise andmepäringu."}, "tags": {"059_d_talk": "g_vocab", "059_t_home": "g_vocab"}},
  "b1b2-060": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded tundide 41–60 teemadel (arvamusartikkel „Digiriik — kõigile või ainult osavatele?”, väide ja lõik, lausepank, klubi teade) vähemalt 60 % ulatuses igas osas.", "g_listen": "Õpilane saab aru kuuest lühiteatest, jutusaatest „Tehisintellekt koolis” ja raamatukogu digiabi juhi intervjuust ning vastab valikvastuste, lünkade ja õige-vale väidetega.", "g_notice": "Õpilane kasutab vahehindamises õigesti umbisikulist tegumoodi, -mine- ja -ja-vorme, kaudset kõnet ja tingivat kõneviisi ning paneb sõnad blogitekstis õigesse vormi.", "g_use": "Õpilane kirjutab klubile umbes 140-sõnalise kirja ja 180-sõnalise andmete kokkuvõtte, räägib 1 minuti oma digireeglitest ja jõuab paariarutelus ühisele seisukohale."}, "tags": {"060_p_clips": "g_listen", "060_p_show": "g_listen", "060_p_listen": "g_listen", "060_p_tf": "g_listen"}},
  "b1b2-061": {"canDo": "Ma selgitan, mis saab minu kodu jäätmetest ja pandipakendist, väljendan muutust ja tulemust (muutub kompostiks, jääb sorteerimata, vähenes) ning räägin majakoosolekul 2 minutit, kuidas meie maja võiks paremini sorteerida.", "goals": {"g_vocab": "Õpilane räägib oma kodu prügist sõnadega jäätmed, pakend, biojäätmed, pandipakend, pant, konteiner, ringlusse võtma, sorteerima, prügila, tooraine ja otsustab, kuhu kaheksa asja lähevad.", "g_read": "Õpilane kontrollib teema avalehe järgi oma oletusi pandipakendi ja jäätmete kohta (Eesti Pandipakend 2025, sorteerimine 40 %, ringlussevõtt 33 %, Haabersti katse) ja põhjendab vastust tekstiga; pakendi märgistuse (pandimärk) järgi otsustab, kuhu asi läheb.", "g_notice": "Õpilane väljendab muutust ja tulemust: muutuma / jääma / minema / tegema + -ks, X-st saab Y, jääma + -mata ning -nema-tegusõnad (vähenes, on paranenud).", "g_use": "Õpilane räägib majakoosolekul 2 minutit maja sorteerimisest ja vastab naabri kahtlustele, räägib uue naabriga viisakalt ja kirjutab juhatusele 160–180-sõnalise ettepaneku."}, "tags": {"061_d_talk": "g_vocab", "061_t_home": "g_vocab", "061_t_sort": "g_read"}},
  "b1b2-062": {"canDo": "Ma loen joonist ja teksti toidu raiskamise kohta, väljendan põhjust ja tagajärge nimisõnaga (soodustuste tõttu, tänu Toidupangale, selle tagajärjel) ning kirjutan andmetest 180–200-sõnalise kokkuvõtte koos oma kommentaariga.", "goals": {"g_vocab": "Õpilane räägib oma külmkapist ja toidu raiskamisest sõnadega toidujäätmed, raiskama, söödav, halvaks minema, kõlblik kuni, märgis, soodustus, ülejääk, annetama, abivajaja.", "g_read": "Õpilane loeb joonist ja teksti (127 kg elaniku kohta, kodude osa 40 %, „parim enne” ja „kõlblik kuni”, Toidupank) ja paneb kokkuvõtte jaoks kirja arvud, võrdlused ja põhjused 1–3 sõnaga.", "g_notice": "Õpilane väljendab põhjust nimisõnaga (omastav + tõttu, tänu + alaleütlev) ja tagajärge sõnadega selle tagajärjel, seetõttu, mistõttu, tegusõna teisel kohal.", "g_use": "Õpilane selgitab joonist kahtlevale korterikaaslasele ja lepib kokku ühe muudatuse, otsustab külmkapimängus iga toidu üle ja kirjutab 180–200-sõnalise kokkuvõtte andmetest koos kommentaariga."}, "tags": {"062_d_talk": "g_vocab", "062_t_home": "g_vocab"}},
  "b1b2-063": {"canDo": "Ma saan kuuldust aru raadioarutelust põlevkivist loobumise üle, räägin -mine-nimisõnade ja arvude võrdlusega (töökohtade kadumine, 4,5 protsendipunkti võrra kõrgem) ning jõuan argumendikaartidega arutelus ühise seisukohani, mida Ida-Virumaa üleminekus kõigepealt teha.", "goals": {"g_vocab": "Õpilane räägib energiast ja tööst sõnadega põlevkivi, kaevandus, tööstus, heitmed, töökoht, töötus, koondama, ümberõpe, üleminek, õiglane.", "g_read": "Õpilane saab aru raadioarutelust „Ida-Virumaa pärast põlevkivi” ja paneb lünka kahe külalise arvud ja argumendid; eristab üleminekut puudutavates lausetes fakti, arvamust ja lubadust.", "g_notice": "Õpilane moodustab -mine-nimisõna omastava sihitisega ja käänab seda (töökohtade kadumist, õppimise eest) ning võrdleb arve (… protsendipunkti võrra kõrgem, kaks korda rohkem kui).", "g_use": "Õpilane jõuab argumendikaartidega arutelus ühise esimese sammuni, räägib Töötukassa nõustajaga oma oskustest ja kirjutab sõbrale Narvas 160–180-sõnalise nõuande."}, "tags": {"063_d_talk": "g_vocab", "063_t_home": "g_vocab"}},
  "b1b2-064": {"canDo": "Ma saan aru ilmahoiatusest ja ametite lühiteadetest, mida kuumalaine ajal teha, koostan naabritega trepikoja kuumaplaani ja kirjutan 180–200-sõnalise teksti „probleem → põhjused → lahendused → järeldus”, kus kasutan vastuväidet (vaatamata …, küll …, kuid, ehkki).", "goals": {"g_vocab": "Õpilane räägib kuumusest ja ohutusest sõnadega kuumalaine, hoiatus, riskirühm, eakas, vedelik, kuumarabandus, jahutama, vari, kiirabi, vaatamata.", "g_read": "Õpilane saab aru viiest üks kord kuuldud lühiteatest kuumalaine kohta (hoiatus, Terviseamet, jahe saal, uuring, kuumarabandus) ja leiab naabrite kaartidelt, kes on riskirühmas ja kes saab aidata.", "g_notice": "Õpilane väljendab vastuväidet ja järeleandmist: vaatamata + alaleütlev, vaatamata sellele, et …; küll …, kuid; ehkki (tegusõna kohe pärast kõrvallauset).", "g_use": "Õpilane koostab naabritega neljast sammust kuumaplaani, täidab oma kodu keskkonnaplaani, helistab rollimängus 112 ja kirjutab 180–200-sõnalise probleemi ja lahenduse teksti."}, "tags": {"064_d_talk": "g_vocab", "064_t_home": "g_vocab"}},
  "b1b2-065": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel „Mina või riik? Mõlemad”, väide ja lõik, vormivalikuga kiri juhatusele, lausepank talgupäevast) keskkonna ja vastutuse teemal vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru neljast teatest (taaraautomaat, ohtlikud jäätmed, Toidupank, puude istutamine) ja korteriühistu esimehe raadiointervjuust maja renoveerimise kohta ning paneb kirja arvud ja põhjused.", "g_notice": "Õpilane kasutab kontrollis õigesti muutuse vorme (-ks, -mata), põhjust nimisõnaga (tõttu, tänu), -mine-nimisõnu ja vastuväidet (vaatamata, küll …, kuid).", "g_use": "Õpilane kirjutab maja juhatusele umbes 140-sõnalise kirja ja 180-sõnalise arutluse ning räägib 1 minuti oma kodu keskkonnaplaanist ja arutleb argumendikaartidega."}, "tags": {"065_p_notes": "g_listen", "065_p_listen": "g_listen", "065_p_tf": "g_listen"}},
  "b1b2-066": {"canDo": "Ma loen valla teavet sotsiaalteenuste kohta ja saan aru umbisikulisest ametlikust tekstist (abivajadust hinnatakse, kulud tasutakse), valin eakale inimesele sobiva teenuse ja räägin sotsiaaltöötajaga selgelt, mida ta vajab.", "goals": {"g_vocab": "Õpilane räägib eakate abist sõnadega teenus, pöörduma, abivajadus, sotsiaaltöötaja, hooldus, hooldekodu, eakas, toetus, hindama, taotlus.", "g_read": "Õpilane kontrollib teema avalehe järgi oma oletusi sotsiaalabi kohta (iga viies elanik 65+, vald korraldab abi, abivajaduse hindamine, koduteenus, häirenupp, hooldereform 2023) ja valib kaheksale olukorrale sobiva teenuse.", "g_notice": "Õpilane kasutab ametlikus tekstis umbisikulist tegumoodi: olevik -takse / -dakse, minevik -ti / -di, täisminevik on + -tud, eitus ei + -ta, terve sihitis nimetavas (otsus tehakse).", "g_use": "Õpilane selgitab sotsiaaltöötajale lähedase olukorda ja lepib kokku järgmise sammu, veenab rollimängus ema abi vastu võtma ja kirjutab sotsiaaltöötajale 160–180-sõnalise kirja."}, "tags": {"066_d_talk": "g_vocab", "066_t_home": "g_vocab"}},
  "b1b2-067": {"canDo": "Ma saan aru vabatahtliku päästja raadiointervjuust, kasutan osalemise tegusõnu õige käändega (osalema milles, liituma millega, vastutama mille eest) ning leian infovahetuse abil endale sobiva vabatahtliku töö ja kirjutan koordinaatorile kandideerimiskirja.", "goals": {"g_vocab": "Õpilane räägib vabatahtlikust tööst sõnadega vabatahtlik, kogukond, ühendus, osalema, liituma, panustama, vastutama, koolitus, ennetama, suitsuandur ja paneb kirja oma plaani „Minu kaks tundi nädalas”.", "g_read": "Õpilane saab aru vabatahtliku päästja raadiointervjuust (uuring: iga neljas-viies elanik, 119 komandot, ennetustöö, aeg ja pere) ja täidab lüngad (Harno B2 kuulamine, osa 3) ning leiab infovahetuses kaardilt ja partnerilt puuduva info.", "g_notice": "Õpilane kasutab tegusõna rektsiooni: osalema milles, liituma millega, huvituma millest, sõltuma millest, panustama millesse, vastutama mille eest, pöörduma kelle poole.", "g_use": "Õpilane küsib infovahetuses puuduvat infot õige käändega, valib kahe võimaluse vahel endale sobiva, helistab koordinaatorile ja kirjutab 160–180-sõnalise kandideerimiskirja."}, "tags": {"067_d_talk": "g_vocab", "067_t_home": "g_vocab", "067_t_plan": "g_vocab", "067_t_gap": "g_read"}},
  "b1b2-068": {"canDo": "Ma saan aru kodakondsuse taotlemise nõuetest, eristan kohustust, luba ja keeldu (peab, ei pea, ei tohi, on vabastatud), räägin nõustajana inimesele, mida ta peab tegema ja mida mitte, ning kirjutan sugulasele nõuandekirja.", "goals": {"g_vocab": "Õpilane räägib dokumentidest ja nõuetest sõnadega kodakondsus, taotlema, elamisluba, nõue, sooritama, sissetulek, vabastama, seaduslik, püsiv, põhiseadus.", "g_read": "Õpilane leiab pere vestlusest ja nõuete kastist kodakondsuse nõuded (8 aastat, B1, põhiseaduse eksam, vabastus hariduse korral, senisest kodakondsusest vabastamine) ja saab aru kolmest nõustamisliini häälsõnumist.", "g_notice": "Õpilane eristab kohustust, luba, keeldu ja kohustuse puudumist (peab, tuleb, on kohustatud, võib, ei tohi, ei pea, on vabastatud) ja kasutab kesksõna reeglites (nõutud, sooritatud).", "g_use": "Õpilane annab nõustajana juhtumi põhjal nõu, küsib rollimängus eksamile registreerimise kohta ja kirjutab sugulasele 160–180-sõnalise nõuandekirja (Harno B2 kirjutamine, osa 1)."}, "tags": {"068_d_talk": "g_vocab", "068_t_home": "g_vocab"}},
  "b1b2-069": {"canDo": "Ma saan aru, kuidas elanik saab vallale ettepaneku teha (märgukiri, allkirjad, kaasav eelarve), võrdlen kahte lahendust kulu ja riski järgi tingivas kõneviisis (see maksaks, paigaldataks, riskiks oleks), esitlen oma kodukoha probleemi lahendust ja kirjutan vallale ametliku ettepaneku.", "goals": {"g_vocab": "Õpilane räägib kohalikust elust sõnadega ettepanek, vallavalitsus, volikogu, pöördumine, allkiri, eelarve, kulu, tähtaeg, lahendus, tänavavalgustus ja kirjutab üles oma kodukoha mured.", "g_read": "Õpilane saab aru valla infotunnist (märgukiri ja 30 päeva, 1 % algatus, rahvaalgatus.ee ja 1000 allkirja, kaasav eelarve) ja võrdleb kolme lahenduse kaarti hinna, aja ja riski järgi.", "g_notice": "Õpilane sõnastab ettepaneku tingivas kõneviisis (maksaks, oleks, väheneks, riskiks oleks) ja umbisikulises tingivas (paigaldataks, ehitataks, toodaks).", "g_use": "Õpilane esitleb komisjonile 2–3 minutit oma ettepanekut ja vastab küsimustele (Harno B2 rääkimine, osa 1), täidab „Minu kodukoha teejuhi” ja kirjutab vallale 180–200-sõnalise märgukirja."}, "tags": {"069_d_talk": "g_vocab", "069_t_home": "g_vocab", "069_t_product": "g_vocab"}},
  "b1b2-070": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel „Kohalik elu ei ole ainult volikogu asi”, väide ja lõik, vormivalikuga kiri vallavalitsusele, lausepank külaraamatukogust) vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru neljast teatest (raamatukogu, suitsuandur, kaasav eelarve, eakate päevakeskus) ja omastehooldaja raadiointervjuust ning paneb kirja arvud ja sammud.", "g_notice": "Õpilane kasutab kontrollis õigesti umbisikulist tegumoodi, tegusõna rektsiooni, kohustuse ja keelu väljendeid (ei pea, ei tohi) ja ettepaneku tingivat kõneviisi.", "g_use": "Õpilane kirjutab vallavalitsusele umbes 140-sõnalise kirja ja 180-sõnalise arutluse, räägib 1 minuti oma kodukoha teejuhist ja arutleb argumendikaartidega."}, "tags": {"070_p_notes": "g_listen", "070_p_listen": "g_listen", "070_p_tf": "g_listen"}},
  "b1b2-071": {"canDo": "Ma saan kuuldust aru lühikestest raadiouudistest, eristan pealkirjas fakti, hinnangut ja oletust kindlust ja hinnangut näitavate sõnade järgi ning räägin toimetuse koosolekul 2 minutit, miks minu pealkiri on aus ja siiski huvitav.", "goals": {"g_vocab": "Õpilane räägib oma uudistest ja pealkirjadest sõnadega pealkiri, väide, fakt, hinnang, oletus, allikas, kinnitama, eksitama, toimetaja, avaldama.", "g_read": "Õpilane saab aru viiest üks kord kuuldud raadiouudisest (bussipilet, lumi, perearst, kuulujutt turust, parandus) ja jagab kaheksa pealkirja faktiks allikaga, hinnanguks ja oletuseks.", "g_notice": "Õpilane muudab väite kindlust (kindlasti, tõenäoliselt, võib-olla, väidetavalt, kuuldavasti; tegusõna teisel kohal) ja tunneb ära hinnangusõnad taas, koguni, alles, ainult.", "g_use": "Õpilane kaitseb toimetuse koosolekul 2 minutit ausat pealkirja, kirjutab kodus uudisnupu ja eraldi arvamuse (180–200 sõna) ning räägib 1 minuti, kuidas ta uudiseid loeb."}, "tags": {"071_d_talk": "g_vocab", "071_t_home": "g_vocab"}},
  "b1b2-072": {"canDo": "Ma loen arvamuslugu ja leian autori seisukoha, tooni ja eesmärgi, annan autori mõtte edasi (autori sõnul, autor möönab, et …, olevat) ning räägin argumendikaartidega arutelus, kuni jõuame ühise otsuseni, mida portaali kommentaariumiga teha.", "goals": {"g_vocab": "Õpilane räägib kommentaaridest ja arvamuslugudest sõnadega arvamuslugu, seisukoht, toon, eesmärk, kommentaar, sõnavabadus, vastutama, möönma, rõhutama, veenma.", "g_read": "Õpilane määrab arvamusloost „Kommentaarium on elutuba, mitte väljak” autori seisukoha, tooni ja eesmärgi (Delfi kaasus 2015) ning eristab raadio kuulajate tunnis argumenti ja rünnakut inimese vastu.", "g_notice": "Õpilane annab autori mõtte edasi (autori sõnul / arvates, autor rõhutab / möönab / kahtleb, et …) ja kasutab kaudset kõneviisi teise inimese väite kohta (olevat, maksvat, ei muutvat).", "g_use": "Õpilane jõuab lugejate nõukogus argumendikaartidega ühise otsuseni, räägib raadios autorile vastu ja kirjutab toimetusele 180–200-sõnalise lugejakirja."}, "tags": {"072_d_talk": "g_vocab", "072_t_home": "g_vocab"}},
  "b1b2-073": {"canDo": "Ma saan aru taskuhäälingu arutelust mõjuisikute reklaami üle, hindan väite tugevust (väide, põhjus, tõend), kasutan hinnangus kesksõnu (makstud, tõendamata, kontrollitav) ning kirjutan mõjuisikule viisaka, kuid selge sõnumi.", "goals": {"g_vocab": "Õpilane räägib soovitustest ja reklaamist sõnadega reklaam, mõjuisik, koostöö, tasu, märgistama, varjatud, tõend, toime, usaldusväärne, tarbija.", "g_read": "Õpilane saab aru taskuhäälingust „Raha ja meie” (jurist ja mõjuisik, Harno L2) ning hindab kolme postituse märgistust ja väidete tugevust.", "g_notice": "Õpilane kasutab hinnangus kesksõnu: -tud (makstud, varjatud, tõestatud), -tav (kontrollitav, äratuntav) ja -mata (tõendamata, märgistamata), -tav käändub.", "g_use": "Õpilane kirjutab mõjuisikule viisaka, kuid selge sõnumi, aitab sõbral kiirlaenu üle otsustada ja kirjutab kodus 180–200-sõnalise arutluse."}, "tags": {"073_d_talk": "g_vocab", "073_t_home": "g_vocab"}},
  "b1b2-074": {"canDo": "Ma loen joonist ja uudist palkade kohta, mõistan keskmise ja mediaani vahet, väljendan hulka ja osa (pool töötajatest, enamik töötajaid, iga teine) ning kirjutan oma meediamenüü ja kokkuvõtte, mis ei moonuta arve ja kus minu arvamus on eraldi.", "goals": {"g_vocab": "Õpilane räägib arvudest uudistes sõnadega keskmine, mediaan, palk, protsent, enamik, kasv, võrdlema, uudis, kokkuvõte, järeldus.", "g_read": "Õpilane vastab joonise ja uudise „Eestlane teenib juba üle 2100 euro” järgi kaheksale lühiküsimusele (Statistikaamet 2026: 2135 ja 1753 eurot, Harno R2b) ja saab aru tädi häälsõnumist.", "g_notice": "Õpilane väljendab hulka ja osa (pool töötajatest teenib, enamik töötajaid, iga teine lugeja, kaks kolmandikku, 6,2 protsendi võrra) ja alustab kokkuvõtet õigesti (artiklis käsitletakse …).", "g_use": "Õpilane selgitab tädile keskmise ja mediaani vahet, paneb kirja oma meediamenüü ja kirjutab kodus 180–220-sõnalise kokkuvõtte, kus tema reaktsioon on eraldi."}, "tags": {"074_d_talk": "g_vocab", "074_t_home": "g_vocab"}},
  "b1b2-075": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel „Kas me loeme veel kaugemale kui pealkiri?”, väide ja lõik, vormiga lugejakiri, lausepank kooli ajalehe faktikontrollist) meedia teemal vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru neljast teatest (raadio, raamatukogu, portaal, valla ajaleht) ja keeleõpetaja raadiointervjuust meedia abil õppimise kohta ning paneb kirja arvud ja soovitused.", "g_notice": "Õpilane kasutab kontrollis õigesti kindluse sõnu, autori mõtte edasiandmist ja kaudset kõneviisi, kesksõnu hinnangus ning hulga ja osa väljendeid.", "g_use": "Õpilane kirjutab Pressinõukogule umbes 140-sõnalise kaebuse ja 180-sõnalise arutluse ning räägib 1 minuti oma meediamenüüst ja arutleb argumendikaartidega."}, "tags": {"075_p_notes": "g_listen", "075_p_listen": "g_listen", "075_p_tf": "g_listen"}},
  "b1b2-076": {"canDo": "Ma kirjutan korteri omanikule 160–200-sõnalise tutvustava kirja, miks sobin üürnikuks, ja lepin telefonis tingimused kokku; seon põhjuse, vastanduse, tingimuse, aja ja tagajärje vähemalt kuue sidendiga (kuigi, ehkki, samal ajal kui, juhul kui, seetõttu, mistõttu).", "goals": {"g_vocab": "Õpilane räägib kodu otsimisest sõnadega üürima, üürileandja, üürnik, kuulutus, sobima, usaldusväärne, tutvustama, tingimus ning valib kolme kuulutuse vahel.", "g_read": "Õpilane saab aru maakleri raadionõuandest (üüriturg 2026, mida omanik kirjast otsib) ja valib kolme lause seast selle, mille omanik meelde jätab.", "g_notice": "Õpilane seob laused sidenditega kuigi, ehkki, kuna, samal ajal kui, juhul kui, seetõttu, mistõttu ja paneb tegusõna kohe pärast seetõttu ning pärast kõrvallauset.", "g_use": "Õpilane lepib telefonis omanikuga kokku vaatamise aja ja kaks tingimust ning kirjutab omanikule 160–200-sõnalise tutvustava kirja."}, "tags": {"076_d_talk": "g_vocab", "076_t_more": "g_vocab", "076_t_home": "g_vocab"}},
  "b1b2-077": {"canDo": "Ma loen teksti Eesti tavadest, mis uustulnukaid üllatavad, ja jutustan raadio lugude võistlusel 1–2 minutit oma esimesest korrast (saunas, jaanipäeval, laulupeol või mujal) nii, et tegusõna on õigel kohal ja tähtis info on lause alguses või lõpus.", "goals": {"g_vocab": "Õpilane räägib uustulnuka kogemustest sõnadega tava, traditsioon, suitsusaun, leil, lõke, laulupidu, üllatama, piinlik, vaikus, harjuma.", "g_read": "Õpilane kontrollib teema avalehe järgi oma oletusi Eesti tavade kohta (suitsusaun UNESCO nimekirjas, jaanipäev, laulupidu, vaikus) ja saab aru eelmise aasta võitja loost.", "g_notice": "Õpilane paneb tegusõna teisele kohale pärast aja- ja kohamäärust, alustab pealauset pärast kõrvallauset tegusõnaga ja rõhutab sõnadega alles, isegi, mitte keegi.", "g_use": "Õpilane jutustab raadio lugude võistlusel 1–2 minutit oma loo, vastab saatejuhi küsimustele ja kirjutab loo 180–200 sõnaga võistluse kodulehele."}, "tags": {"077_d_talk": "g_vocab", "077_t_home": "g_vocab"}},
  "b1b2-078": {"canDo": "Ma saan aru ujula või spordikeskuse kodukorrast ja arvustustest, annan sõbrale nõu, kuidas esimest korda minna, ja kirjutan 180–200-sõnalise arvustuse spordikohast; kasutan kesksõnu (-v, -tav, -nud, -tud) ja des-vormi, et kirjeldus oleks lühike ja täpne.", "goals": {"g_vocab": "Õpilane räägib spordikohast sõnadega ujula, bassein, riietusruum, pesema, kapp, kehtiv, lubatud, keelatud, arvustus, algaja.", "g_read": "Õpilane leiab ujula kodukorrast (A–F) vastuse sõbra küsimustele ja loeb kaht arvustust, et sõbrale nõu anda.", "g_notice": "Õpilane kasutab kesksõnu -v, -tav, -nud, -tud ja des-vormi (kehtiv pilet, lukustatav kapp, kogenud ujuja, ostetud pilet, duši all käies) ning teeb kõrvallausest lühema kirjelduse.", "g_use": "Õpilane annab infolüngaga vestluses sõbrale kolm nõuannet, arutleb argumendikaartidega tasuta ujumiskursuse üle ja kirjutab 180–200-sõnalise arvustuse spordikohast."}, "tags": {"078_d_talk": "g_vocab", "078_t_info": "g_read", "078_t_home": "g_vocab"}},
  "b1b2-079": {"canDo": "Ma saan aru lastevanemate koosolekust, eristan fakti ja kuulujuttu, annan teiste sõnad täpselt edasi (direktori sõnul …, väidetavalt olevat …) ning räägin naabrile 1–2 minutit, mis otsustati, ja esitan koolile viisaka palve tingivas kõneviisis.", "goals": {"g_vocab": "Õpilane räägib koosolekutest ja infost sõnadega koosolek, lapsevanem, otsus, kuulujutt, allikas, kinnitama, üleminek, õppekeel, emakeel, palve.", "g_read": "Õpilane saab aru lastevanemate koosolekust eestikeelsele õppele ülemineku kohta (õige või vale) ja leiab naabri sõnumitest kuulujutud, mida tuleb faktiga kontrollida.", "g_notice": "Õpilane valib kõneviisi funktsiooni järgi: allikas (kelle sõnul), kaudne kõneviis kontrollimata info jaoks (olevat), umbisikuline otsuse jaoks (otsustati) ja tingiv viisakas palve (Kas te saaksite …?).", "g_use": "Õpilane räägib naabrile 1–2 minutit, mis koosolekul otsustati, peatab kuulujutu viisakalt, täidab oma tekstimapi ja kirjutab 160–200-sõnalise kokkuvõtte neile, kes ei saanud tulla."}, "tags": {"079_d_talk": "g_vocab", "079_t_home": "g_vocab"}},
  "b1b2-080": {"goals": {"g_read": "Õpilane lahendab Harno B2 vormis lugemisülesanded (arvamusartikkel „Vaba aeg — luksus või kõigi õigus?”, väide ja lõik, valiklüngad kirjas raamatukogule, lausepank laulupeost, spordikeskuse teade) vähemalt 80 % ulatuses.", "g_listen": "Õpilane saab aru kuuest lühiteatest, jutusaatest raamatukogu kohta ja külapäeva korraldaja intervjuust ning paneb kirja arvud, põhjused ja otsused.", "g_notice": "Õpilane kasutab proovieksamis õigesti sidendeid, sõnajärge, kesksõnu ja des-vormi, kõneviisi funktsiooni järgi ning moodulite 13–15 vorme (tõttu, vaatamata).", "g_use": "Õpilane kirjutab spordikeskusele umbes 140-sõnalise kirja ja 180-sõnalise kokkuvõtte andmetest, räägib 1 minuti oma tekstimapist ja jõuab paarisarutelus ühisele seisukohale."}, "tags": {"080_p_show": "g_listen", "080_p_listen": "g_listen", "080_p_tf": "g_listen", "080_t_clips": "g_listen"}},
  "b1b2-081": {"goals": {"g_read": "Õpilane leiab arvamusloost seisukoha, argumendid, vastuargumendi ja järelduse, järeldab autori hoiaku ning kasutab loo argumente oma plaanis.", "g_notice": "Õpilane seob lõigud sildadega (lisaks sellele, samas, seetõttu, kokkuvõttes), paneb tegusõna silla järel teisele kohale ja kirjutab kõnekeelse lause poolametlikult.", "g_use": "Õpilane räägib külma ülesandena 1 minuti, kaitseb väitlusel seisukohta argumendikaartidega ja kirjutab umbes 180-sõnalise arvamusloo päris allikale viidates."}, "tags": {"081_t_plan": "g_read"}},
  "b1b2-082": {"goals": {"g_read": "Õpilane saab aru umbes 3-minutilisest raadiointervjuust ametnikuga, vastab 12 küsimusele ja kasutab ametniku nõuandeid oma kirja kavas.", "g_notice": "Õpilane muudab järsu lause viisakaks tingiva kõneviisiga (Sooviksin…, Oleksin tänulik…, Kas saaksite…) ja kasutab ametliku kirja vorme.", "g_use": "Õpilane lahendab telefonis ametnikuga ootamatu takistuse, lepib kokku uue tähtaja ja kirjutab ametnikule umbes 140-sõnalise kirja."}, "tags": {"082_t_plan": "g_read"}},
  "b1b2-083": {"goals": {"g_read": "Õpilane leiab probleemartiklist probleemi, põhjused, tagajärjed, lahendused ja hinnangu, järeldab autori seisukoha ja kasutab artikli fakte oma kõne kavas.", "g_notice": "Õpilane moodustab -mine-nimisõnu, kasutab põhjuse ja tagajärje keelt (… tõttu, mistõttu, selle tagajärjel) ja ütleb lause ametlikumalt.", "g_use": "Õpilane räägib koosolekul pärast 2-minutilist ettevalmistust 1 minuti probleemist ja lahendusest ning kirjutab sellest umbes 180-sõnalise teksti päris andmetega."}, "tags": {"083_t_plan": "g_read"}},
  "b1b2-084": {"goals": {"g_read": "Õpilane saab aru umbes 3-minutilisest raadiosaatest hindajaga, otsustab 12 väite õigsuse ja kasutab hindaja mõtteid väitluse plaanis.", "g_notice": "Õpilane parandab vea, põhjendab parandust reegliga (sihitis, rektsioon, sõnajärg, tegevusnimi) ja annab tagasisidet viisakalt.", "g_use": "Õpilane kaitseb väitlusel oma seisukohta ja kirjutab keelekoolile umbes 140-sõnalise kirja, mille ta enne saatmist ise parandab."}, "tags": {"084_t_plan": "g_read"}},
  "b1b2-085": {"goals": {"g_vocab": "Õpilane kasutab kirjas ja kõnes ilma sõnaraamatuta mooduli sõnu (seisukoht, põhjendama, taotlus, lahendus) ja registrile sobivaid väljendeid.", "g_notice": "Õpilane parandab oma tüüpvead (sihitis, rektsioon, sõnajärg, tegevusnimi, sidend) ja kontrollib oma kirja hindamisjuhendi järgi.", "g_use": "Õpilane kirjutab iseseisvalt kolleegile umbes 140-sõnalise kirja sobivas registris ja räägib pärast 2-minutilist ettevalmistust 1 minuti ning arutleb."}, "tags": {"085_t_wpart": "g_vocab", "085_t_spart": "g_vocab", "085_t_wscore": "g_notice"}},
  "b1b2-086": {"canDo": "Ma räägin pärast kahte minutit ettevalmistust ühe minuti (seisukoht, argument näitega, vastuargument, järeldus), seon mõtted suulise kõne sildadega ja vastan komisjoni ootamatule küsimusele.", "goals": {"g_read": "Õpilane saab aru umbes 3-minutilisest raadiointervjuust keeleeksamite hindajaga, vastab 12 küsimusele ja kasutab hindaja nõuandeid oma sõnavõtu kavas.", "g_notice": "Õpilane seob kõne osad sildadega (esimene põhjus on, võtame näiteks, samas tuleb tunnistada, seega leian), paneb tegusõna silla järel teisele kohale ja ütleb kirjaliku lause loomulikult sõnavõtus.", "g_use": "Õpilane räägib külma ülesandena 1 minuti, peab sisekonkursi vestlusel üheminutilise sõnavõtu, reageerib ootamatule infole ja kirjutab komisjonile umbes 140-sõnalise kirja."}, "tags": {"086_t_plan": "g_read"}},
  "b1b2-087": {"canDo": "Ma pean läbirääkimist argumendikaartidega, reageerin muutunud tingimusele ja kirjutan juhatusele umbes 180-sõnalise ettepaneku, kus pakun kompromissi tingivas kõneviisis.", "goals": {"g_read": "Õpilane leiab artiklist läbirääkimise viis sammu, järeldab autori hoiaku ja kasutab artikli nõuandeid oma väitluse plaanis.", "g_notice": "Õpilane muudab nõudmise ettepanekuks tingiva kõneviisiga (maksaksime, kas sobiks, mis oleks, kui) ja ütleb järsu lause läbirääkimise keeles.", "g_use": "Õpilane jõuab väitlusel argumendikaartidega ühisele otsusele, reageerib uuele tingimusele ja kirjutab juhatusele umbes 180-sõnalise ettepaneku."}, "tags": {"087_t_plan": "g_read"}},
  "b1b2-088": {"canDo": "Ma kirjutan arvamusartiklist kokkuvõtte koos kommentaariga, annan teiste sõnad edasi (autori sõnul, olevat), hoian oma arvamuse eraldi ning kaitsen seda koosolekul argumendikaartidega.", "goals": {"g_read": "Õpilane leiab arvamusartiklist autori peamõtte, kaks argumenti ja vastuargumendi, eristab autori, õpetaja ja kriitikute häält ning järeldab autori hoiaku.", "g_notice": "Õpilane annab teiste sõnad edasi (autori sõnul, tema sõnul, kaudne kõneviis olevat, lahkuvat) ja muudab ümberjutustuse lühikeseks kokkuvõtteks.", "g_use": "Õpilane räägib paralleelülesandena 1 minuti hoolekogus, kaitseb väitlusel seisukohta ja kirjutab päris ERR-i artiklist umbes 180-sõnalise kokkuvõtte koos kommentaariga."}, "tags": {"088_t_mono": "g_read"}},
  "b1b2-089": {"goals": {"g_read": "Õpilane lahendab täismahus Harno B2 kuulamise ja lugemise osad ajapiiri sees vähemalt 60% igas osas.", "g_listen": "Õpilane saab aru kuulamistekstidest „Viis lühiklippi (kuuled kaks korda)”, „Intervjuu (märksõnad)”, „Loeng” ja „Intervjuu kahe külalisega (märksõnad)” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane teisendab laused pärast lugemisosa ja kontrollib arutluses sõnajärge, vorme ja sidusust.", "g_use": "Õpilane kirjutab juhile seletuskirja ja arutluse ning peab kõne ja paarisarutelu ilma abita."}, "tags": {"089_t_w2": "g_notice", "089_d_l1": "g_listen", "089_d_l2": "g_listen", "089_d_l3": "g_listen", "089_d_l4": "g_listen", "089_d_c12": "g_listen", "089_d_tf": "g_listen"}},
  "b1b2-090": {"goals": {"g_read": "Õpilane lahendab paralleelse Harno B2 kuulamise ja lugemise osad ning kannab punktid tabelisse.", "g_listen": "Õpilane saab aru kuulamistekstidest „Viis lühiklippi (kuuled kaks korda)”, „Intervjuu (märksõnad)”, „Loeng” ja „Intervjuu kahe külalisega (märksõnad)” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane näitab keeleosas tööks piisavat grammatilist täpsust (vead, sõnajärg).", "g_use": "Õpilane kirjutab keelekooli juhile kirja ja arutluse, räägib ning koostab järgmise sammu plaani."}, "tags": {"090_d_l1": "g_listen", "090_d_l2": "g_listen", "090_d_l3": "g_listen", "090_d_l4": "g_listen", "090_d_c12": "g_listen", "090_d_tf": "g_listen"}},
  "b1b2-k01": {"canDo": "Ma moodustan sõna põhivormid ainsuses ja mitmuses ning valin lauses õige vormi: kindel asi, kelle oma või hulk ja eitus.", "goals": {"g_notice": "Õpilane moodustab nimetava, omastava ja osastava ainsuses ja mitmuses (tubade, tube, laste, lapsi) ja põhjendab vormi valikut.", "g_read": "Õpilane valib Kadri kirjas ja korteriühistu teates sõnale sobiva käände: arv, hulk ja eitus osastavas, omanik ja kaassõna omastavas.", "g_use": "Õpilane kirjeldab oma kodu ja kirjutab ostunimekirja, kasutades arve, eitust ning sõnu palju ja mitu."}},
  "b1b2-k02": {"canDo": "Ma kasutan sise- ja väliskohakäändeid ainsuses ja mitmuses ning lühikest sisseütlevat (kooli, tuppa, majja) ja juhatan teed vigadeta.", "goals": {"g_read": "Õpilane leiab Mia päevikust ja lausetest, kus keegi on, kuhu ta läheb ja kust tuleb.", "g_notice": "Õpilane moodustab sise- ja väliskohakäände ainsuses ja mitmuses (poodides, naabritelt) ja lühikese sisseütleva (kooli, tuppa, majja).", "g_use": "Õpilane juhatab teed ja kirjutab oma nädala teekondadest vähemalt kuue kohakäändega."}},
  "b1b2-k03": {"canDo": "Ma kasutan rajavat (kuni reedeni), ilmaütlevat (ilma loata) ja kaasaütlevat käänet (koos naabritega) ainsuses ja mitmuses.", "goals": {"g_read": "Õpilane mõistab vestluses, remondireeglites ja väljendites, mida tähendavad -ni (piir), -ta (puudumine) ja -ga (koos, vahend).", "g_notice": "Õpilane moodustab rajava, ilmaütleva ja kaasaütleva ainsuses ja mitmuses ning ühildab omadus- ja arvsõna (suure noaga, kahe töömehega).", "g_use": "Õpilane räägib oma nädalavahetusest ja kirjutab ehitajale sõnumi vormidega kuni …-ni, ilma …-ta ja koos …-ga."}},
  "b1b2-k04": {"canDo": "Ma tunnen sõna kuju järgi ära tema muuttüübi ja moodustan tüüpsõna järgi ainsuse omastava ja osastava ning mitmuse vormid; kahtluse korral kontrollin Sõnaveebist.", "goals": {"g_read": "Õpilane tunneb sõna kuju järgi ära tema tüübi (maa, kana, kõne, õpetaja, raamat, inimene, tuba, liige) ja leiab Sõnaveebist sõna kolm põhivormi.", "g_notice": "Õpilane moodustab tüüpsõna järgi ainsuse omastava ja osastava ning mitmuse nimetava, omastava ja osastava (kapi, kappi, kapid, kappide, kappe) ja tunneb astmevahelduse ära.", "g_use": "Õpilane räägib ja kirjutab oma kodust, asjadest ja linnast eri tüüpi sõnadega õigetes vormides (arvud, palju, mitu, eitus)."}},
};
